def solve(grid):
    """
    Transform the input grid according to the discovered rule.

    The grid contains a few unique numbers (appearing exactly once).  Each such
    number is a “central” cell.  All other non‑zero numbers are “satellites”.
    A satellite that lies in the same row or column as a central cell is moved
    to the cell adjacent to the central one in the direction of the satellite
    (i.e. one step closer).  The central cells stay in place, all other cells
    become zero.

    The function returns the transformed grid in the same format as the input
    (list of lists of integers).
    """
    if not grid:
        return []

    rows = len(grid)
    cols = len(grid[0])

    from collections import Counter
    freq = Counter()
    for row in grid:
        for v in row:
            freq[v] += 1

    # locate central cells (values that occur exactly once)
    central = []
    for i in range(rows):
        for j in range(cols):
            v = grid[i][j]
            if v != 0 and freq[v] == 1:
                central.append((i, j, v))

    # start with an empty grid
    out = [[0] * cols for _ in range(rows)]

    # place central cells (they may be overwritten by satellites, so we set
    # them again later)
    for i, j, v in central:
        out[i][j] = v

    # move each satellite onto the neighbour of its central cell
    for r, c, _ in central:
        for i in range(rows):
            for j in range(cols):
                v = grid[i][j]
                if v == 0 or freq[v] <= 1:   # ignore zeros and central values
                    continue

                # the satellite must share either the same row or the same column
                if i == r:                     # same row
                    if j < c:
                        nr, nc = r, c - 1
                    elif j > c:
                        nr, nc = r, c + 1
                    else:
                        continue
                elif j == c:                   # same column
                    if i < r:
                        nr, nc = r - 1, c
                    elif i > r:
                        nr, nc = r + 1, c
                    else:
                        continue
                else:
                    continue    # not aligned with this central

                # ensure the target position is inside the grid
                if 0 <= nr < rows and 0 <= nc < cols:
                    out[nr][nc] = v

    # make sure central cells are not overwritten
    for i, j, v in central:
        out[i][j] = v

    return out

